import {TOPICS, defaultPreferences, validatePreferences, buildSampleSummary} from './summaries.mjs';
import {QUALITY, DEMEANOR, dayKey, shiftDay, localStamp, sleepMetrics, validateRating, formatDuration, medicationAt, duplicateDose, revise, overlappingSleep, scheduledRoutines, seed} from './model.mjs';
const KEY = 'together-care-demo-v2';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = () => crypto.randomUUID();
const dateLabel = (day, short = false) => new Date(`${day}T12:00:00`).toLocaleDateString(undefined, short ? {month:'short',day:'numeric'} : {weekday:'long',month:'long',day:'numeric'});
const timeLabel = time => time ? new Date(`2000-01-01T${time}`).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'}) : '';
const stampLabel = stamp => `${dateLabel(stamp.slice(0,10),true)} · ${timeLabel(stamp.slice(11,16))}`;
const now = () => new Date().toISOString();
let state, storageError = '', cacheReady = false;
try { const stored = JSON.parse(localStorage.getItem(KEY) || 'null'); state = stored?.version === 2 ? stored : seed(); } catch { state = seed(); storageError = 'Saved demo data could not be read. New sample data is shown. Export any new work before closing.'; }
state.summaryPreferences ||= {};
let summaryUser=state.actor;
let page = location.hash.slice(1) || 'today', selectedDay = dayKey(), trackerKind = 'all', noteCategory = 'All', modalSave, lastFocus;
if (!['today','medications','appointments','schedule','trackers','updates','summaries'].includes(page)) page = 'today';

function notify(text) { $('toast').textContent = text; $('toast').classList.add('show'); clearTimeout(notify.timer); notify.timer = setTimeout(() => $('toast').classList.remove('show'),4000); }
function persist() {
  const previousSaved = state.lastSaved; state.lastSaved = now();
  try { localStorage.setItem(KEY,JSON.stringify(state)); storageError = ''; }
  catch { state.lastSaved = previousSaved; storageError = 'Changes are only in this open tab: browser storage is unavailable or full. Export a backup before closing.'; }
}
function commit(action, message = 'Saved on this device') { action(); persist(); render(); notify(storageError || message); }
function navigate(next) { page = next; location.hash = next; render(); }
function canManage() { return state.actor === 'Mom' || state.actor === 'You'; }
function requireManager() { if (!canManage()) throw new Error('In this demo, Mom and You can maintain the care plan. Switch the demo caregiver to continue.'); }
function field(name, label, type = 'text', value = '', options = '') { return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${options}></label>`; }
function textarea(name,label,value='',options='') { return `<label class="field"><span>${label}</span><textarea name="${name}" ${options}>${esc(value)}</textarea></label>`; }
function select(name,label,choices,value='',required=true) { return `<label class="field"><span>${label}</span><select name="${name}" ${required?'required':''}>${choices.map(c=>{const [v,l]=Array.isArray(c)?c:[c,c];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`; }
function btn(label,action,value='',secondary=false) { return `<button class="button ${secondary?'secondary ':''}small" data-action="${action}" data-id="${esc(value)}">${label}</button>`; }
function header(eyebrow,title,subtitle,actions='') { return `<div class="page-heading"><div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`; }

function badges(record) { return `<span class="badge ${['Given','Done'].includes(record.status)?'green':'orange'}">${esc(record.status)}</span>`; }
function correctionField(record) { return record ? textarea('correction','Reason for correction','','required maxlength="500"') : ''; }
function history(record) { return record?.history?.length ? `<details class="detail-section"><summary>Correction history (${record.history.length})</summary>${record.history.map(h=>`<div class="history-item"><strong>${esc(h.author)}</strong> · ${stampLabel(localStamp(new Date(h.at)))}<br>${esc(h.reason)}<br><span class="meta">Previously: ${esc(h.previous.status || (h.previous.rating ? DEMEANOR[h.previous.rating-1] : h.previous.quality ? `${QUALITY[h.previous.quality-1]} · ${stampLabel(h.previous.start)} → ${stampLabel(h.previous.end)}` : h.previous.text))}</span></div>`).join('')}</details>` : ''; }
function openModal(title,body,onSave,label='Save') {
  if($('modal').open)$('modal').close();
  lastFocus = document.activeElement; modalSave = onSave;
  $('modal-title').textContent = title; $('modal-body').innerHTML = body; $('form-error').textContent = ''; $('submit-modal').textContent = label;
  $('modal-actions').style.display = onSave ? 'flex' : 'none'; $('modal').showModal();
}
function closeModal() { $('modal').close(); modalSave = null; lastFocus?.focus?.(); }
$('close-modal').onclick = closeModal; $('cancel-modal').onclick = closeModal;
$('modal').addEventListener('click',e=> { if(e.target === $('modal')) {const r=$('modal').getBoundingClientRect(); if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();} });
$('modal-form').onsubmit = e => {
  e.preventDefault(); if (!modalSave) return;
  try { modalSave(Object.fromEntries(new FormData(e.target))); closeModal(); }
  catch(error) { $('form-error').textContent = error.message; }
};

$('demo-info').onclick = demoInfo;
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['today','medications','appointments','schedule','trackers','updates','summaries'].includes(p)){page=p;render();}});
window.addEventListener('online',render); window.addEventListener('offline',render);
window.addEventListener('storage',e=>{if(e.key===KEY && e.newValue){try{const incoming=JSON.parse(e.newValue);if(incoming.version===2){state=incoming;render();notify('Updated from another tab on this device');}}catch{}}});
function offlineNotice() {
  return `${storageError?`<div class="offline-banner" role="alert">${esc(storageError)}</div>`:''}${!navigator.onLine?'<div class="offline-banner"><strong>Offline · Changes stay on this device.</strong><br>There is no family sync in this demo. Other caregivers’ actions are unavailable.</div>':''}`;
}
function render() {
  document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
  $('connection').className = `connection ${navigator.onLine?'':'offline'}`;
  $('connection').textContent = storageError?'● Unsaved changes':navigator.onLine?'● Saved on this device':'● Offline · Local only';
  const views = {summaries:summariesView,schedule:scheduleView,today:todayView,medications:medicationView,appointments:appointmentsView,trackers:trackersView,updates:updatesView};
  $('main').innerHTML = offlineNotice()+views[page]();
}
function dayControls(label) { return `<div class="date-row"><button class="button secondary" data-action="previous-day" aria-label="Previous day">←</button><div class="day-label"><strong>${selectedDay===dayKey()?'Today':dateLabel(selectedDay)}</strong><span>${selectedDay===dayKey()?dateLabel(selectedDay):''}</span></div><button class="button secondary" data-action="next-day" aria-label="Next day">→</button><label class="choose-date">Choose date <input id="selected-day" aria-label="Selected day" type="date" value="${selectedDay}"></label>${selectedDay!==dayKey()?'<button class="button secondary" data-action="reset-day">Back to today</button>':''}</div>`; }

function getDoses(day=selectedDay) {
  return state.meds.flatMap(m=>{const v=medicationAt(m,day); return v?v.times.map(time=>({med:m,version:v,time,record:duplicateDose(state.doses,m.id,day,time)})):[];}).sort((a,b)=>a.time.localeCompare(b.time));
}
function routineRecord(r) { return state.routineRecords.find(item=>item.day===selectedDay&&item.routineId===r.id); }
function todayView() {
 const sleeps=state.sleeps.filter(x=>x.end.slice(0,10)===selectedDay).sort((a,b)=>b.end.localeCompare(a.end));
 const behavior=state.demeanor.filter(x=>x.observed.slice(0,10)===selectedDay).sort((a,b)=>b.observed.localeCompare(a.observed));
 const sleep=sleeps[0],observed=behavior[0];
 return header('','Dad’s daily care','',canManage()?btn('＋ Add to schedule','add-schedule'):'')+dayControls('Day')+`<section aria-labelledby="record-heading" class="record-section"><h2 id="record-heading">Record care</h2><div class="quick-actions"><button data-action="choose-dose" class="quick-action"><span aria-hidden="true" class="quick-icon">✚</span><strong>Record medication</strong></button><button data-action="sleep" class="quick-action"><span aria-hidden="true" class="quick-icon">☾</span><strong>Record sleep</strong></button><button data-action="demeanor" class="quick-action"><span aria-hidden="true" class="quick-icon">◡</span><strong>Record behavior</strong></button><button data-action="add-note" class="quick-action"><span aria-hidden="true" class="quick-icon">✎</span><strong>Add note</strong></button></div></section><section class="card schedule-home"><div class="section-head"><h2>The day’s schedule</h2></div>${scheduleRows()}</section><section class="day-records"><h2>What’s been recorded</h2><div class="full-grid"><section class="card"><div class="section-head"><h3>Sleep</h3>${sleep?btn('View / change','sleep',sleep.id,true):''}</div>${sleep?`<p class="record-value">${formatDuration(sleepMetrics(sleep.start,sleep.end,sleep.awakeMinutes).asleepMinutes)} <span>estimated asleep</span></p><p>${timeLabel(sleep.start.slice(11,16))} – ${timeLabel(sleep.end.slice(11,16))} · ${QUALITY[sleep.quality-1]}</p><p class="meta">${sleep.type} · ${esc(sleep.author)}</p>`:`<p>No sleep recorded for this day.</p>${btn('Record sleep','sleep','',true)}`}</section><section class="card"><div class="section-head"><h3>Behavior</h3>${observed?btn('View / change','demeanor',observed.id,true):''}</div>${observed?`<p class="record-value">${observed.rating} / 5 <span>${DEMEANOR[observed.rating-1]}</span></p><p>${esc(observed.notes)||'No additional note.'}</p><p class="meta">${timeLabel(observed.observed.slice(11,16))} · ${esc(observed.author)}</p>`:`<p>No behavior recorded for this day.</p>${btn('Record behavior','demeanor','',true)}`}</section></div></section><div class="home-links"><button class="button secondary" data-page="medications">Medication plan & dose history</button><button class="button secondary" data-page="trackers">Sleep & behavior history</button><button class="button secondary" data-page="updates">Read family notes</button><button class="button secondary" data-page="summaries">Care summaries</button></div>`;
}

function routinesForDay(day) { return scheduledRoutines(state.routines,day); }
function scheduleRows() {
 const doses=getDoses(),routines=routinesForDay(selectedDay),appointments=state.appointments.filter(a=>a.date===selectedDay);
 const periods=['Morning','Afternoon','Evening'];
 const periodOf=time=>Number(time.slice(0,2))<12?'Morning':Number(time.slice(0,2))<18?'Afternoon':'Evening';
 const rows=[...doses.map(d=>({period:periodOf(d.time),time:d.time,html:doseRow(d)})),...routines.map(r=>({period:r.time?periodOf(r.time):r.period,time:r.time||'',html:routineRow(r)})),...appointments.map(a=>({period:periodOf(a.time),time:a.time,html:`<div class="activity appointment-activity"><div class="row-time">${timeLabel(a.time)}</div><div class="activity-content"><h3>${esc(a.title)}</h3><p>${esc(a.location)}</p><p>Ride: ${esc(a.transport)}</p></div>${btn('View appointment','appointment',a.id,true)}</div>`}))];
 if(!rows.length)return '<p class="empty">Nothing on the schedule for this day.</p>';
 return periods.map(period=>{const items=rows.filter(r=>r.period===period).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));return items.length?`<section class="schedule-period"><h3 class="period-title">${period}</h3>${items.map(r=>r.html).join('')}</section>`:'';}).join('');
}
function scheduleView(){return header('','Schedule','',canManage()?btn('＋ Add to schedule','add-schedule'):'')+dayControls('Day')+`<section class="card">${scheduleRows()}</section><div class="subheading"><h2>Upcoming appointments</h2></div><div class="list-cards">${state.appointments.filter(a=>a.date>=selectedDay).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(appointmentPreview).join('')||'<section class="card"><p>No upcoming appointments.</p></section>'}</div>`;}
function chooseDose(){openModal('Record medication',`<p class="intro-copy">${dateLabel(selectedDay)}</p>${getDoses().map(d=>doseRow(d)).join('')||'<p>No medications scheduled for this day.</p>'}<p class="notice-inline">No record does not mean a dose was missed.</p>`,null);}
function scheduleForm(){requireManager();openModal('Add to schedule',select('type','What are you adding?',['Activity','Appointment'])+field('title','Name','text','','required maxlength="150" placeholder="Lunch, a walk, or a doctor’s visit"')+`<div class="field-row">${field('date','Date','date',selectedDay,'required')}${field('time','Time (optional for activities)','time','')}</div><div id="activity-fields">${select('repeat','Repeat',['Just this day','Every day'])}${select('period','Part of day (if no time)',['Morning','Afternoon','Evening'])}</div><div id="appointment-fields" hidden>${field('location','Location','text','','maxlength="250"')}${field('provider','Doctor / care team (optional)','text','','maxlength="150"')}${select('transport','Who is taking Dad?',['Unassigned','Mom','You','Sibling'])}</div>${textarea('details','Notes (optional)','','maxlength="2000"')}`,data=>{
 requireManager();if(!data.title.trim())throw new Error('Enter a name.');
 if(data.type==='Appointment'&&(!data.time||!data.location.trim()))throw new Error('Add the appointment time and location.');
 commit(()=>{if(data.type==='Appointment')state.appointments.push({id:id(),title:data.title.trim(),date:data.date,time:data.time,location:data.location.trim(),provider:data.provider.trim(),transport:data.transport,preparation:data.details.trim(),questions:[],outcome:'',author:state.actor,created:now()});else state.routines.push({id:id(),name:data.title.trim(),period:data.period,time:data.time,repeat:data.repeat==='Every day'?'daily':'once',details:data.details.trim(),effectiveDate:data.date});},'Added to schedule');
 },'Add to schedule');
 $('modal-form').elements.type.onchange=e=>{$('activity-fields').hidden=e.target.value==='Appointment';$('appointment-fields').hidden=e.target.value!=='Appointment';};
}
function doseRow(d) { return `<div class="activity"><div class="row-time">${timeLabel(d.time)}</div><div class="activity-content"><h3>${esc(d.version.name)}</h3><p>${esc(d.version.dose)}</p>${d.record?`<div class="status-line">${badges(d.record)}<span class="meta">${d.record.actual?timeLabel(d.record.actual.slice(11,16))+' · ':''}${esc(d.record.author)}</span></div>`:'<span class="badge">No dose recorded</span>'}</div>${btn(d.record?'View record':'Record dose','dose',`${d.med.id}|${d.time}`,!!d.record)}</div>`; }

function routineRow(r) {const record=routineRecord(r);return `<div class="activity"><div class="row-time">${r.time?timeLabel(r.time):'Any time'}</div><div class="activity-content"><h3>${esc(r.name)}</h3>${r.details?`<p>${esc(r.details)}</p>`:''}${record?`<div class="status-line">${badges(record)}<span class="meta">${esc(record.author)}</span></div>`:''}</div>${btn(record?'View record':'Mark done',record?'routine':'mark-routine',r.id,true)}</div>`;}

function appointmentPreview(a){return `<section class="card accent"><p class="appointment-label">APPOINTMENT</p><h2 class="appointment-title">${esc(a.title)}</h2><p class="appointment-info"><strong>${dateLabel(a.date,true)} · ${timeLabel(a.time)}</strong><br>${esc(a.location)}<br>Transportation: ${esc(a.transport)}</p>${btn('View appointment →','appointment',a.id,true)}</section>`;}
function medicationView(){
 const doses=getDoses();
 return header('','Medication plan','',canManage()?btn('＋ Add medication','add-med'):'')+dayControls('Plan for')+(!canManage()?'<p class="soft-note">Mom maintains the plan. You can record doses as the demo sibling.</p>':'')+`<div class="full-grid">${state.meds.map(m=>{const v=medicationAt(m,selectedDay);if(!v)return '';return `<section class="card med-card"><div class="med-top"><span class="med-symbol">✚</span><div><h2>${esc(v.name)}</h2><p class="meta">${esc(v.strength)} · Fictional sample</p></div></div><dl class="definition"><div><dt>DOSE & ROUTE</dt><dd>${esc(v.dose)}<br>${esc(v.route)}</dd></div><div><dt>SCHEDULE</dt><dd>${v.times.map(timeLabel).join(' · ')}</dd></div><div><dt>INSTRUCTIONS</dt><dd>${esc(v.instructions)}</dd></div><div><dt>PLAN SOURCE</dt><dd>${esc(v.source)}<br><span class="meta">Effective ${dateLabel(v.effectiveDate,true)}</span></dd></div></dl><div class="med-bottom"><span class="meta">Reviewed ${dateLabel(v.reviewed,true)} · ${esc(v.author)}</span>${canManage()?btn('Update plan','edit-med',m.id,true):''}</div></section>`;}).join('')||'<section class="card empty">No medication plan for this day.</section>'}</div><div class="subheading"><h2>Scheduled doses</h2><span class="meta">${dateLabel(selectedDay,true)}</span></div><section class="card">${doses.map(doseRow).join('')||'<p class="empty">No scheduled doses.</p>'}</section><div class="subheading"><h2>Recent dose history</h2><span class="meta">Latest 30 records</span></div><section class="card table-wrap"><table><thead><tr><th>MEDICATION</th><th>SCHEDULED</th><th>OUTCOME</th><th>RECORDED BY</th><th></th></tr></thead><tbody>${state.doses.slice().sort((a,b)=>(b.scheduledDay+b.scheduledTime).localeCompare(a.scheduledDay+a.scheduledTime)).slice(0,30).map(d=>`<tr><td>${esc(d.name)}<small>${esc(d.dose)}</small></td><td>${dateLabel(d.scheduledDay,true)}<small>${timeLabel(d.scheduledTime)}</small></td><td>${badges(d)}<small>${d.actual?stampLabel(d.actual):esc(d.reason)}</small></td><td>${esc(d.author)}${d.history?.length?'<small>Corrected · history available</small>':''}</td><td>${btn('Review','dose-history',d.id,true)}</td></tr>`).join('')||'<tr><td colspan="5">No dose records yet.</td></tr>'}</tbody></table></section>`;
}
function appointmentsView(){return header('LOOKING AHEAD','Appointments','Questions, preparation, and follow-up in one place.',canManage()?btn('＋ Add appointment','add-appointment'):'')+`<div class="list-cards">${state.appointments.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>`<section class="card appointment-card"><div class="calendar-tile"><small>${new Date(a.date+'T12:00').toLocaleDateString(undefined,{month:'short'}).toUpperCase()}</small><strong>${Number(a.date.slice(8))}</strong></div><div><h2>${esc(a.title)}</h2><p class="meta">${dateLabel(a.date)} · ${timeLabel(a.time)}</p><p class="appointment-info">${esc(a.provider)}<br>${esc(a.location)}</p><span class="badge ${a.transport==='Unassigned'?'orange':'green'}">${a.transport==='Unassigned'?'Transportation unassigned':`Ride: ${esc(a.transport)}`}</span> <span class="badge">${a.questions.length} questions</span>${a.outcome?' <span class="badge green">Visit notes saved</span>':''}</div>${btn('View details','appointment',a.id,true)}</section>`).join('')||'<section class="card empty">No appointments yet. Add the next visit when you’re ready.</section>'}</div>`;}
function trackersView(){
 const days=Array.from({length:7},(_,i)=>shiftDay(selectedDay,i-6));
 const sleeps=state.sleeps.filter(s=>days.includes(s.end.slice(0,10))).sort((a,b)=>b.end.localeCompare(a.end));
 const observations=state.demeanor.filter(d=>days.includes(d.observed.slice(0,10))).sort((a,b)=>b.observed.localeCompare(a.observed));
 return header('A SMALL DAILY CHECK-IN','Sleep & behavior history','',`${btn('Record sleep','sleep')} ${btn('Record behavior','demeanor','',true)}`)+dayControls('Seven days ending')+`<div class="tracker-intro"><p>Behavior: 1 = very unsettled; 5 = calm & content. This is a personal observation, not a medical score.</p></div><div class="full-grid tracker-grid"><section class="card"><div class="section-head"><h2>Sleep at a glance</h2><span class="badge blue">Estimated asleep</span></div><p class="meta">Sleep periods appear on the day they ended. Awake time is subtracted.</p><div class="sleep-chart">${days.map(day=>{const records=state.sleeps.filter(s=>s.end.slice(0,10)===day),total=records.reduce((sum,s)=>sum+sleepMetrics(s.start,s.end,s.awakeMinutes).asleepMinutes,0);return `<div class="chart-row"><span>${dateLabel(day,true)}</span><div class="bar-track">${records.length?`<div class="bar-fill" style="width:${Math.min(total/960*100,100)}%"></div>`:''}</div><strong>${records.length?formatDuration(total):'—'}</strong></div>`;}).join('')}</div><p class="meta">— = no entry. Includes naps; bars show up to 16 hours. The written total is complete.</p></section><section class="card"><div class="section-head"><h2>Behavior at a glance</h2><span class="badge">1–5</span></div><p class="meta">Each dot is one observation. No entry is different from a low score.</p><div class="demeanor-chart">${days.map(day=>{const records=state.demeanor.filter(d=>d.observed.slice(0,10)===day).sort((a,b)=>a.observed.localeCompare(b.observed));return `<div class="demeanor-row"><span>${dateLabel(day,true)}</span><div class="demeanor-dots">${records.length?records.map(d=>`<button class="demeanor-dot score-${d.rating}" data-action="demeanor" data-id="${d.id}" aria-label="${esc(`${stampLabel(d.observed)}: ${d.rating} of 5, ${DEMEANOR[d.rating-1]}`)}" title="${esc(`${timeLabel(d.observed.slice(11,16))} · ${DEMEANOR[d.rating-1]}`)}">${d.rating}</button>`).join(''):'<span class="meta">No entry</span>'}</div></div>`;}).join('')}</div><div class="scale-key"><span>1 · Very unsettled</span><span>5 · Calm & content</span></div></section></div><div class="subheading"><h2>Recorded entries</h2><label class="meta">Show <select id="tracker-kind" aria-label="Tracker type"><option value="all" ${trackerKind==='all'?'selected':''}>Sleep & behavior</option><option value="sleep" ${trackerKind==='sleep'?'selected':''}>Sleep</option><option value="demeanor" ${trackerKind==='demeanor'?'selected':''}>Behavior</option></select></label></div><div class="list-cards">${[...sleeps.map(s=>({...s,kind:'sleep',sort:s.end})),...observations.map(d=>({...d,kind:'demeanor',sort:d.observed}))].filter(e=>trackerKind==='all'||trackerKind===e.kind).sort((a,b)=>b.sort.localeCompare(a.sort)).map(e=>trackerEntry(e)).join('')||'<section class="card empty">No entries in this seven-day window. Record a check-in or choose another date.</section>'}</div>`;
}
function trackerEntry(e){const sleep=e.kind==='sleep'; const metrics=sleep?sleepMetrics(e.start,e.end,e.awakeMinutes):null;return `<section class="card tracker-entry"><div class="journal-head"><div><span class="eyebrow">${sleep?'SLEEP':'BEHAVIOR'}</span><h3>${sleep?`${formatDuration(metrics.asleepMinutes)} estimated asleep`:`${e.rating}/5 · ${DEMEANOR[e.rating-1]}`}</h3></div>${btn('View / change',sleep?'sleep':'demeanor',e.id,true)}</div><p class="meta">${sleep?`${stampLabel(e.start)} → ${stampLabel(e.end)}<br>${e.type} · ${QUALITY[e.quality-1]} quality · ${e.awakeMinutes}m awake during the period`:`${stampLabel(e.observed)}${e.context?' · '+esc(e.context):''}`}</p>${e.notes?`<p class="tracker-note">${esc(e.notes)}</p>`:''}<p class="meta">${esc(e.author)}${e.history?.length?` · ${e.history.length} correction${e.history.length>1?'s':''}`:''}</p></section>`;}
function updatesView(){const notes=state.notes.filter(n=>noteCategory==='All'||n.category===noteCategory).sort((a,b)=>b.observed.localeCompare(a.observed));return header('','Family notes','',btn('Add note','add-note'))+`<div class="filter-row"><label>Category <select id="note-category" aria-label="Update category">${['All','Sleep','Appetite','Mood','Mobility','Pain','Other'].map(c=>`<option ${c===noteCategory?'selected':''}>${c}</option>`).join('')}</select></label><span class="meta">${notes.length} entries</span></div><div class="list-cards">${notes.map(n=>`<section class="card journal-entry"><div class="journal-head"><div><span class="author">${esc(n.author)}</span><p class="meta">Observed ${stampLabel(n.observed)}</p></div><div><span class="badge">${esc(n.category)}</span> ${n.followup?'<span class="badge orange">Needs follow-up</span>':''}</div></div><p>${esc(n.text)}</p><div class="journal-foot"><span class="meta">${n.editedBy?`Corrected by ${esc(n.editedBy)}`:`Entered ${stampLabel(localStamp(new Date(n.created)))}`}</span>${btn('View / change','edit-note',n.id,true)}</div></section>`).join('')||'<section class="card empty">No updates in this category.</section>'}</div>`;}
function sleepForm(recordId) {
 const record=state.sleeps.find(s=>s.id===recordId), day=selectedDay;
 openModal(record?'Change sleep entry':'Record sleep',`<p class="intro-copy">For overnight sleep, the start date is usually yesterday.</p>${select('type','Sleep period',['Overnight','Nap'],record?.type||'Overnight')}<div class="field-row">${field('start','Went to sleep','datetime-local',record?.start||`${shiftDay(day,-1)}T22:00`,'required')}${field('end','Woke up','datetime-local',record?.end||`${day}T06:30`,'required')}</div>${field('awakeMinutes','Minutes awake during the night (estimate)','number',record?.awakeMinutes??0,'required min="0" step="1"')}<div id="sleep-estimate" class="soft-note" aria-live="polite"></div><fieldset class="rating-field"><legend>How well did Dad sleep?</legend><div class="quality-options">${QUALITY.map((q,i)=>`<label class="rating-option"><input type="radio" name="quality" value="${i+1}" ${record?.quality===i+1?'checked':''} required><span>${q}</span></label>`).join('')}</div></fieldset>${textarea('notes','Notes (optional)',record?.notes||'','maxlength="2000" placeholder="Waking, restlessness, or anything you noticed…"')}${correctionField(record)}${history(record)}`,data=>{
   sleepMetrics(data.start,data.end,data.awakeMinutes);const quality=validateRating(data.quality);
   const overlap=overlappingSleep(state.sleeps,data.start,data.end,record?.id);
   if(overlap)throw new Error(`This overlaps the sleep entry ending ${stampLabel(overlap.end)}. Review that entry or adjust the times so sleep is not counted twice.`);
   const changes={type:data.type,start:data.start,end:data.end,awakeMinutes:Number(data.awakeMinutes),quality,notes:data.notes.trim()};
   commit(()=>{if(record){state.sleeps=state.sleeps.map(s=>s.id===record.id?revise(s,changes,state.actor,data.correction):s);}else{state.sleeps.push({id:id(),...changes,author:state.actor,created:now(),history:[]});}},'Sleep entry saved');
 },record?'Save correction':'Save sleep');
 const estimate=()=>{try{const form=$('modal-form');const m=sleepMetrics(form.elements.start.value,form.elements.end.value,form.elements.awakeMinutes.value);$('sleep-estimate').textContent=`${formatDuration(m.asleepMinutes)} estimated asleep · ${formatDuration(m.intervalMinutes)} total period`;}catch(e){$('sleep-estimate').textContent=e.message;}};
 ['start','end','awakeMinutes'].forEach(name=>$('modal-form').elements[name].addEventListener('input',estimate));estimate();
}
function demeanorForm(recordId){
 const record=state.demeanor.find(d=>d.id===recordId);
 openModal(record?'Change behavior entry':'Record behavior',`<p class="intro-copy">How does Dad seem? Choose one description.</p>${field('observed','When?','datetime-local',record?.observed||`${selectedDay}T${localStamp().slice(11)}`,'required')}<fieldset class="rating-field"><legend>How does Dad seem?</legend><div class="rating-options">${DEMEANOR.map((label,i)=>`<label class="rating-option"><input type="radio" name="rating" value="${i+1}" ${record?.rating===i+1?'checked':''} required><span class="rating-number">${i+1}</span><span>${label}</span></label>`).join('')}</div></fieldset><details class="optional-fields"><summary>Add context (optional)</summary>${select('context','Context (optional)',['','Morning','Afternoon','Evening','After a meal','After an activity','Other'],record?.context||'',false)}</details>${textarea('notes','What did you notice? (optional)',record?.notes||'','maxlength="2000" placeholder="What was happening? What seemed to help?"')}${correctionField(record)}${history(record)}`,data=>{
 const rating=validateRating(data.rating);if(!data.observed)throw new Error('Enter the observation time.');
 const changes={observed:data.observed,rating,context:data.context,notes:data.notes.trim()};
 commit(()=>{if(record){state.demeanor=state.demeanor.map(d=>d.id===record.id?revise(d,changes,state.actor,data.correction):d);}else state.demeanor.push({id:id(),...changes,author:state.actor,created:now(),history:[]});},'Behavior saved');
 },record?'Save correction':'Save behavior');
}
function doseForm(medId,time,historyId){
 const historical=state.doses.find(d=>d.id===historyId),med=state.meds.find(m=>m.id===(historical?.medId||medId)),v=medicationAt(med,historical?.scheduledDay||selectedDay);
 const record=historical||duplicateDose(state.doses,medId,selectedDay,time),day=record?.scheduledDay||selectedDay,scheduledTime=record?.scheduledTime||time;
 openModal(record?'Review dose record':'Record a dose',`<div class="soft-note"><strong>${esc(record?.name||v.name)}</strong><br>${esc(record?.dose||v.dose)} · Scheduled ${dateLabel(day,true)} at ${timeLabel(scheduledTime)}<br>${esc(v.instructions)}</div><p class="intro-copy">If you are unsure whether the dose was given, check with the caregiver first.</p>${select('status','Outcome',['Given','Skipped','Held'],record?.status||'Given')}${field('actual','Time given','datetime-local',record?.actual||(day===dayKey()?localStamp():`${day}T${scheduledTime}`))}${textarea('reason','Reason / reference to instructions',record?.reason||'','maxlength="1000" placeholder="Required for Skipped or Held"')}${correctionField(record)}${history(record)}`,data=>{
 if(data.status==='Given'&&!data.actual)throw new Error('Enter the actual time given.');
 if(data.status!=='Given'&&!data.reason.trim())throw new Error('Add the reason this dose was skipped or held.');
 if(!record&&duplicateDose(state.doses,med.id,day,scheduledTime))throw new Error('This dose already has an entry. Close and review the existing record.');
 const changes={status:data.status,actual:data.status==='Given'?data.actual:'',reason:data.reason.trim()};
 commit(()=>{if(record)state.doses=state.doses.map(d=>d.id===record.id?revise(d,changes,state.actor,data.correction):d);else state.doses.push({id:id(),medId:med.id,name:v.name,dose:v.dose,scheduledDay:day,scheduledTime,...changes,author:state.actor,created:now(),history:[]});},'Dose record saved');
 },record?'Save correction':'Save record');
}
function routineForm(routineId){const routine=state.routines.find(r=>r.id===routineId),record=routineRecord(routine);openModal('Record routine',`<div class="soft-note"><strong>${esc(routine.name)}</strong><br>${esc(routine.details)}</div>${select('status','Outcome',['Done','Skipped'],record?.status||'Done')}${textarea('notes','Note (optional)',record?.notes||'','maxlength="1000"')}${correctionField(record)}${history(record)}`,data=>{commit(()=>{const changes={status:data.status,notes:data.notes.trim()};if(record)state.routineRecords=state.routineRecords.map(r=>r.id===record.id?revise(r,changes,state.actor,data.correction):r);else state.routineRecords.push({id:id(),routineId,day:selectedDay,...changes,author:state.actor,created:now(),history:[]});},'Routine recorded');});}
function addRoutine(){requireManager();openModal('Add a daily routine',field('name','Routine','text','','required maxlength="120" placeholder="A familiar daily activity"')+select('period','Part of the day',['Morning','Afternoon','Evening'])+textarea('details','Helpful details (optional)','','maxlength="1000"')+field('effectiveDate','Starts on','date',selectedDay,'required'),data=>{requireManager();commit(()=>state.routines.push({id:id(),name:data.name.trim(),period:data.period,details:data.details.trim(),effectiveDate:data.effectiveDate}),'Daily routine added');});}
function noteForm(recordId){const record=state.notes.find(n=>n.id===recordId);openModal(record?'Change note':'Add note',textarea('text','What happened?',record?.text||'','required maxlength="5000" placeholder="A small observation or something the family should know…"')+field('observed','When?','datetime-local',record?.observed||`${selectedDay}T${localStamp().slice(11)}`,'required')+select('category','Category',['Other','Sleep','Appetite','Mood','Mobility','Pain'],record?.category||'Other')+`<label class="checkbox-field"><input type="checkbox" name="followup" ${record?.followup?'checked':''}> Needs family follow-up</label>`+correctionField(record)+history(record),data=>{if(!data.text.trim())throw new Error('Add a short update.');const changes={text:data.text.trim(),observed:data.observed,category:data.category,followup:data.followup==='on'};commit(()=>{if(record)state.notes=state.notes.map(n=>n.id===record.id?revise(n,changes,state.actor,data.correction):n);else state.notes.push({id:id(),...changes,author:state.actor,created:now(),history:[]});},'Family update saved');},record?'Save correction':'Save update');}
function medicationForm(medId){requireManager();const med=state.meds.find(m=>m.id===medId),v=med?medicationAt(med,selectedDay)||med.versions.at(-1):null;openModal(med?'Update medication plan':'Add medication',`<p class="intro-copy">Mom maintains this plan. Enter instructions from a reviewed source. All sample medications are fictional.</p>${field('name','Medication name','text',v?.name||'','required maxlength="120"')}${field('strength','Strength','text',v?.strength||'','required maxlength="120"')}<div class="field-row">${field('dose','Dose','text',v?.dose||'','required maxlength="120"')}${field('route','Route','text',v?.route||'By mouth','required maxlength="120"')}</div>${field('times','Daily times (24-hour, comma separated)','text',v?.times.join(', ')||'08:00','required placeholder="08:00, 20:00"')}${textarea('instructions','Instructions',v?.instructions||'','required maxlength="2000"')}${field('source','Reviewed source','text',v?.source||'','required maxlength="200" placeholder="Visit summary, prescription label…"')}${field('effectiveDate','Change takes effect on','date',selectedDay,'required')}<p class="soft-note">Saving creates a dated plan version. Previous dose records and earlier plans are retained. This demo supports fixed daily schedules; as-needed plans are a later addition.</p>`,data=>{
 requireManager();const times=[...new Set(data.times.split(',').map(t=>t.trim()))].sort();if(!times.length||times.some(t=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(t)))throw new Error('Use times such as 08:00, 20:00.');
 const version={name:data.name.trim(),strength:data.strength.trim(),dose:data.dose.trim(),route:data.route.trim(),instructions:data.instructions.trim(),times,source:data.source.trim(),effectiveDate:data.effectiveDate,reviewed:dayKey(),author:state.actor,created:now()};
 if(!version.name||!version.dose)throw new Error('Enter a medication name and dose.');
 if(med&&data.effectiveDate<dayKey())throw new Error('Plan updates must take effect today or later to preserve earlier plans.');
 commit(()=>{if(med)med.versions.push(version);else state.meds.push({id:id(),versions:[version]});},'Medication plan saved');
 },'Save reviewed plan');}
function appointmentForm(appointmentId){requireManager();const a=state.appointments.find(a=>a.id===appointmentId);openModal(a?'Edit appointment':'Add appointment',field('title','Visit title','text',a?.title||'','required maxlength="150"')+field('provider','Provider / care team','text',a?.provider||'','maxlength="150"')+`<div class="field-row">${field('date','Date','date',a?.date||selectedDay,'required')}${field('time','Time','time',a?.time||'14:00','required')}</div>`+field('location','Location','text',a?.location||'','required maxlength="250"')+select('transport','Transportation',['Unassigned','Mom','You','Sibling'],a?.transport||'Unassigned')+textarea('preparation','Preparation instructions',a?.preparation||'','maxlength="2000"'),data=>{requireManager();if(!data.title.trim()||!data.location.trim())throw new Error('Enter a title and location.');const changes={...data,title:data.title.trim(),editedBy:state.actor,editedAt:now()};commit(()=>{if(a)state.appointments=state.appointments.map(item=>item.id===a.id?{...item,...changes}:item);else state.appointments.push({id:id(),...changes,questions:[],outcome:'',author:state.actor,created:now()});},'Appointment saved');});}
function appointmentDetail(appointmentId){const a=state.appointments.find(a=>a.id===appointmentId);openModal(a.title,`<p class="appointment-info"><strong>${dateLabel(a.date)} · ${timeLabel(a.time)}</strong><br>${esc(a.provider)}<br>${esc(a.location)}<br>Transportation: ${esc(a.transport)}</p><div class="detail-actions">${canManage()?btn('Edit appointment','edit-appointment',a.id,true):''}${btn('Add a question','question',a.id,true)}${btn('Add visit outcome','outcome',a.id,true)}</div><div class="detail-section"><h3>Preparation</h3><p>${esc(a.preparation)||'No instructions entered.'}</p></div><div class="detail-section"><h3>Questions to ask</h3>${a.questions.map(q=>`<div class="question">${esc(q.text)}<small>Added by ${esc(q.author)}</small></div>`).join('')||'<p class="meta">No questions yet.</p>'}</div><div class="detail-section"><h3>Visit outcome & next steps</h3><p>${esc(a.outcome)||'No visit notes yet.'}</p></div>`,null);}
function questionForm(appointmentId){closeModal();const a=state.appointments.find(a=>a.id===appointmentId);openModal('Add an appointment question',`<p class="intro-copy">${esc(a.title)} · ${dateLabel(a.date,true)}</p>${textarea('question','Question','','required maxlength="1500"')}`,data=>{if(!data.question.trim())throw new Error('Enter a question.');commit(()=>a.questions.push({text:data.question.trim(),author:state.actor,created:now()}),'Question added');});}
function outcomeForm(appointmentId){closeModal();const a=state.appointments.find(a=>a.id===appointmentId);openModal('Visit outcome',textarea('outcome','Instructions, notes & next steps',a.outcome,'required maxlength="5000"')+'<p class="soft-note">Medication changes need Mom’s review in the medication plan. Saving visit notes does not change the plan.</p>',data=>{commit(()=>{a.outcome=data.outcome.trim();a.outcomeAuthor=state.actor;a.outcomeUpdated=now();},'Visit outcome saved');});}
function helpForm(){openModal('Offer to help',`<p class="intro-copy">${dateLabel(selectedDay)} · ${esc(state.actor)}</p>${textarea('text','How can you help?','','required maxlength="1000" placeholder="I can bring lunch or take Dad to the appointment…"')}`,data=>{if(!data.text.trim())throw new Error('Describe your offer.');commit(()=>state.help.push({id:id(),day:selectedDay,text:data.text.trim(),author:state.actor,created:now()}),'Offer saved');});}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`together-demo-${dayKey()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Demo backup downloaded');}
function demoInfo(){openModal('Your family walkthrough',`<p class="intro-copy">This is a functional local prototype using fictional sample information. Entries stay in this browser on this computer. Choose a caregiver below to demonstrate family roles. This is not a sign-in system.</p><div class="soft-note"><strong>What works</strong><br>Daily routines, scheduled dose records and corrections, appointments, family notes, sleep and demeanor trackers, and local saving.</div><p class="intro-copy">There is no family-device sync, live Mayo access, AI transcription, medication reminder delivery, or secure account system yet. Use fictional information for this walkthrough.</p><label class="profile">Demo caregiver <select id="actor" aria-label="Demo caregiver">${['Mom','You','Sibling'].map(a=>`<option ${a===state.actor?'selected':''}>${a}</option>`).join('')}</select></label><div class="demo-options">${btn('Export a demo backup','export','',true)}${btn('Reset to fictional sample data','reset','',true)}</div><p class="meta" id="offline-readiness">${cacheReady?'Offline page cache is ready.':'Offline page cache is preparing or unavailable.'} Changes remain local even when online.</p>`,null);}
function resetDemo(){closeModal();openModal('Reset the demo?',`<p class="intro-copy">This removes your entries from this browser and restores fictional sample data. Export a backup first if you want to keep the walkthrough changes.</p>`,()=>{state=seed();state.summaryPreferences={};selectedDay=dayKey();commit(()=>{},'Sample data restored');},'Reset demo');}
const actions={
 'open-sample-details':()=>{$('sample-summary-details').hidden=false;},'summary-settings':summarySettings,'summary-preview':summaryPreview,'mark-routine':routineId=>{if(state.routineRecords.some(r=>r.routineId===routineId&&r.day===selectedDay))return routineForm(routineId);commit(()=>state.routineRecords.push({id:id(),routineId,day:selectedDay,status:'Done',author:state.actor,notes:'',created:now(),history:[]}),'Activity marked done');},'add-schedule':scheduleForm,'choose-dose':chooseDose,'previous-day':()=>{selectedDay=shiftDay(selectedDay,-1);render();},'next-day':()=>{selectedDay=shiftDay(selectedDay,1);render();},'sleep':sleepForm,'demeanor':demeanorForm,'dose':value=>{const [med,time]=value.split('|');doseForm(med,time);},'dose-history':value=>doseForm(null,null,value),
 'routine':routineForm,'add-routine':addRoutine,'add-note':()=>noteForm(),'edit-note':noteForm,'add-med':()=>medicationForm(),'edit-med':medicationForm,
 'add-appointment':()=>appointmentForm(),'edit-appointment':value=>{closeModal();appointmentForm(value);},'appointment':appointmentDetail,'question':questionForm,'outcome':outcomeForm,'help':helpForm,
 'reset-day':()=>{selectedDay=dayKey();render();},'export':exportData,'reset':resetDemo
};
document.addEventListener('click',e=>{const pageButton=e.target.closest('[data-page]');if(pageButton){navigate(pageButton.dataset.page);return;}const button=e.target.closest('[data-action]');if(!button)return;try{actions[button.dataset.action]?.(button.dataset.id);}catch(error){notify(error.message);}});
document.addEventListener('change',e=>{if(e.target.id==='summary-user'){summaryUser=e.target.value;render();}if(e.target.id==='actor'){commit(()=>state.actor=e.target.value,'Demo caregiver changed');}if(e.target.id==='selected-day'&&e.target.value){selectedDay=e.target.value;render();}if(e.target.id==='tracker-kind'){trackerKind=e.target.value;render();}if(e.target.id==='note-category'){noteCategory=e.target.value;render();}});
function registerAgentTools(){
 const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();
 const tools=[{name:'read_family_demo',description:'Read the current local demo observations, schedules and records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>JSON.parse(JSON.stringify(state))},
 {name:'navigate_family_demo',description:'Navigate to an existing care screen without changing records.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['today','medications','appointments','schedule','trackers','updates','summaries']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||!['today','medications','appointments','schedule','trackers','updates','summaries'].includes(input.page))throw new Error('Unknown screen');navigate(input.page);return{page};}}];
 for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
persist();render();registerAgentTools();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{cacheReady=true;}).catch(()=>{});}
function preferencesFor(user) { return {...defaultPreferences(),...state.summaryPreferences[user]}; }
function weekdayLabels() { return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']; }
function preferenceDescription(p) {
 const days=p.weekdays.map(d=>weekdayLabels()[Number(d)]).join(', ');
 return `${p.frequency==='daily'?'Every day':days} at ${timeLabel(p.time)} (${p.timeZone.replaceAll('_',' ')})`;
}
function summariesView() {
 const p=preferencesFor(summaryUser);
 return header('','Care summaries','Choose how and when you want updates.')+`<div class="summary-demo-notice"><strong>Local preview only</strong><p>Settings are saved here. No AI is called and no email or text is sent.</p></div><label class="field summary-user-field"><span>Whose summary?</span><select id="summary-user">${['Mom','You','Sibling'].map(user=>`<option ${summaryUser===user?'selected':''}>${user}</option>`).join('')}</select></label><div class="full-grid"><section class="card"><div class="section-head"><h2>${esc(summaryUser)}’s settings</h2><span class="badge ${p.enabled?'green':''}">${p.enabled?'Scheduled preference saved':'Off'}</span></div><dl class="definition"><div><dt>DELIVERY</dt><dd>${p.channel==='email'?'Email summary':'Text with a secure link'}${p.destination?`<br>${esc(p.destination)}`:''}</dd></div><div><dt>SCHEDULE</dt><dd>${esc(preferenceDescription(p))}</dd></div><div><dt>COVERS</dt><dd>${p.coverage==='week'?'Previous 7 complete days':'Previous complete day'}</dd></div><div><dt>TOPICS</dt><dd>${p.topics.map(esc).join(', ')}</dd></div></dl>${btn('Change summary settings','summary-settings',summaryUser)}</section><section class="card"><h2>See what you would receive</h2><p>Preview a sample based on the demo’s saved records.</p><p class="meta">Email includes the summary. Text contains a short notice and a secure link in the full app.</p>${btn('Preview sample summary','summary-preview',summaryUser,true)}<p class="notice-inline">The preview is assembled from recorded entries. It is not an AI-generated assessment.</p></section></div><section class="card calendar-plan"><h2>Calendar connection</h2><p>We’ll connect your mom’s existing calendar after confirming whether its events are stored in iCloud, Google, or another account.</p><p class="meta">The full-app plan keeps a separate Dad’s care calendar. No calendar is connected in this demo.</p></section>`;
}
function summarySettings(user=summaryUser) {
 const p=preferencesFor(user),zones=[...new Set([p.timeZone,'America/Los_Angeles','America/Denver','America/Chicago','America/New_York','America/Phoenix','Pacific/Honolulu','Europe/London','UTC'])];
 openModal(`${user}’s summary settings`,`<p class="soft-note">Use fictional contact details. This demo will not send messages.</p><label class="checkbox-field"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Receive scheduled summaries</label>${select('channel','Send by',[['email','Email — summary in the message'],['text','Text — short notice with a secure link']],p.channel)}<div id="summary-destination-field">${field('destination',p.channel==='email'?'Email address':'Phone number with country code',p.channel==='email'?'email':'tel',p.destination,'placeholder="'+(p.channel==='email'?'mom@example.com':'+12025550123')+'"')}</div>${select('frequency','How often?',[['daily','Every day'],['weekly','Once a week'],['selected','Selected days']],p.frequency)}<fieldset id="summary-weekdays" class="rating-field" ${p.frequency==='daily'?'hidden':''}><legend>Delivery day${p.frequency==='weekly'?'':'s'}</legend><div class="weekdays">${weekdayLabels().map((day,i)=>`<label class="checkbox-field"><input type="checkbox" name="weekdays" value="${i}" ${p.weekdays.includes(String(i))?'checked':''}> ${day}</label>`).join('')}</div></fieldset><div class="field-row">${field('time','Delivery time','time',p.time,'required')}${select('timeZone','Time zone',zones,p.timeZone)}</div>${select('coverage','Period to summarize',[['day','Previous complete day'],['week','Previous 7 complete days']],p.coverage)}<fieldset class="rating-field"><legend>Include</legend>${TOPICS.map(topic=>`<label class="checkbox-field"><input name="topics" type="checkbox" value="${topic}" ${p.topics.includes(topic)?'checked':''}> ${topic}</label>`).join('')}</fieldset>`,data=>{
 const formData=new FormData($('modal-form'));
 const prefs=validatePreferences({...data,enabled:data.enabled==='on',weekdays:formData.getAll('weekdays'),topics:formData.getAll('topics')});
 commit(()=>{state.summaryPreferences[user]=prefs;summaryUser=user;},'Summary preferences saved. No messages will be sent in this demo.');
 },'Save settings');
 const form=$('modal-form');
 form.elements.channel.onchange=e=>{const input=form.elements.destination;input.value='';input.type=e.target.value==='email'?'email':'tel';input.placeholder=e.target.value==='email'?'mom@example.com':'+12025550123';$('summary-destination-field').querySelector('span').textContent=e.target.value==='email'?'Email address':'Phone number with country code';};
 form.elements.frequency.onchange=e=>{$('summary-weekdays').hidden=e.target.value==='daily';$('summary-weekdays').querySelector('legend').textContent=e.target.value==='weekly'?'Choose one delivery day':'Delivery days';};
}
function summaryPreview(user=summaryUser) {
 const p=preferencesFor(user),sample=buildSampleSummary(state,p),email=p.channel==='email';
 openModal(`${user}’s ${email?'email':'text'} preview`,`<div class="summary-demo-notice"><strong>Sample preview · No AI used</strong><p>No message will be sent.</p></div>${email?`<div class="message-preview"><p><strong>Subject:</strong> Dad’s care summary · ${dateLabel(sample.end,true)}</p><p><strong>To:</strong> ${esc(p.destination)||'Your email address'}</p></div>`:`<div class="sms-preview"><p>Your care summary for ${dateLabel(sample.end,true)} is ready.</p><button type="button" class="button secondary" data-action="open-sample-details">View summary</button><p class="meta">The full app will use a link that requires family sign-in. No medical details are included in this text preview.</p></div>`}<div id="sample-summary-details" ${email?'':'hidden'}><p class="meta">Recorded care: ${dateLabel(sample.start,true)}${sample.start!==sample.end?' – '+dateLabel(sample.end,true):''}. Uses records saved on this device.</p>${sample.sections.map(section=>`<section class="detail-section"><h3>${section.title}</h3>${section.items.map(item=>`<p>${esc(item)}</p>`).join('')}${section.sources.length?`<details><summary>View source records</summary><div class="summary-source-links">${section.sources.map(source=>btn(esc(source.label),source.kind,source.id,true)).join('')}</div></details>`:''}</section>`).join('')}${sample.missing.length?`<section class="detail-section"><h3>Missing information</h3>${sample.missing.map(item=>`<p>${esc(item)}</p>`).join('')}</section>`:''}<p class="soft-note">A summary of recorded observations. No diagnoses or medication advice.</p></div>`,null);
}
